-- Sprint 30: governed AI. Additive and idempotent; no existing data is removed.
CREATE SCHEMA IF NOT EXISTS orcafacil;
CREATE TABLE IF NOT EXISTS orcafacil.ai_provider_settings (id uuid PRIMARY KEY, account_id uuid NOT NULL, is_enabled boolean NOT NULL DEFAULT false, mode varchar(32) NOT NULL DEFAULT 'RulesOnly', provider varchar(80), chat_model varchar(120), embedding_model varchar(120), protected_credential text, monthly_limit integer NOT NULL DEFAULT 0, daily_user_limit integer NOT NULL DEFAULT 0, retention_days integer NOT NULL DEFAULT 30, allow_rag boolean NOT NULL DEFAULT false, allow_document_analysis boolean NOT NULL DEFAULT false, allow_drafts boolean NOT NULL DEFAULT false, allow_suggestions boolean NOT NULL DEFAULT false, allow_assisted_actions boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ai_provider_settings_account ON orcafacil.ai_provider_settings(account_id) WHERE NOT is_deleted;
CREATE TABLE IF NOT EXISTS orcafacil.ai_governance_policies (id uuid PRIMARY KEY, account_id uuid NOT NULL, allow_financial_data boolean NOT NULL DEFAULT false, allow_cost_margin boolean NOT NULL DEFAULT false, allow_customer_data boolean NOT NULL DEFAULT true, allow_documents boolean NOT NULL DEFAULT false, allow_commercial_drafts boolean NOT NULL DEFAULT false, allow_financial_drafts boolean NOT NULL DEFAULT false, allow_suggestions boolean NOT NULL DEFAULT false, allow_automatic_critical_actions boolean NOT NULL DEFAULT false CHECK (allow_automatic_critical_actions = false), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ai_governance_account ON orcafacil.ai_governance_policies(account_id) WHERE NOT is_deleted;
CREATE TABLE IF NOT EXISTS orcafacil.ai_knowledge_bases (id uuid PRIMARY KEY, account_id uuid NOT NULL, name varchar(160) NOT NULL, description text, visibility varchar(32) NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_knowledge_bases_account ON orcafacil.ai_knowledge_bases(account_id, is_active);
CREATE TABLE IF NOT EXISTS orcafacil.ai_knowledge_base_items (id uuid PRIMARY KEY, account_id uuid NOT NULL, knowledge_base_id uuid NOT NULL REFERENCES orcafacil.ai_knowledge_bases(id), source_type varchar(60) NOT NULL, source_entity_id varchar(120) NOT NULL, title varchar(240) NOT NULL, content_text text NOT NULL, content_hash varchar(128) NOT NULL, visibility varchar(32) NOT NULL, indexed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ai_kb_item_account_source ON orcafacil.ai_knowledge_base_items(account_id, source_type, source_entity_id, content_hash) WHERE NOT is_deleted;
CREATE TABLE IF NOT EXISTS orcafacil.ai_usage_logs (id uuid PRIMARY KEY, account_id uuid NOT NULL, user_id uuid NOT NULL, operation_type varchar(80) NOT NULL, provider varchar(80) NOT NULL, mode varchar(32) NOT NULL, estimated_tokens integer, estimated_cost numeric(18,6), duration_ms integer NOT NULL, status varchar(32) NOT NULL, sanitized_error text, correlation_id varchar(100) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_ai_usage_account_created ON orcafacil.ai_usage_logs(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_rag_queries (id uuid PRIMARY KEY, account_id uuid NOT NULL, user_id uuid NOT NULL, sanitized_query text NOT NULL, confidence varchar(24) NOT NULL, limitations text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orcafacil.ai_rag_query_sources (id uuid PRIMARY KEY, account_id uuid NOT NULL, rag_query_id uuid NOT NULL REFERENCES orcafacil.ai_rag_queries(id), source_type varchar(60) NOT NULL, source_entity_id varchar(120) NOT NULL, title varchar(240) NOT NULL, source_url text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_ai_rag_sources_account_query ON orcafacil.ai_rag_query_sources(account_id, rag_query_id);
CREATE TABLE IF NOT EXISTS orcafacil.ai_action_drafts (id uuid PRIMARY KEY, account_id uuid NOT NULL, requested_by_user_id uuid NOT NULL, action_type varchar(60) NOT NULL, sanitized_payload text NOT NULL, status varchar(24) NOT NULL DEFAULT 'PendingReview', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.ai_action_approvals (id uuid PRIMARY KEY, account_id uuid NOT NULL, action_draft_id uuid NOT NULL REFERENCES orcafacil.ai_action_drafts(id), reviewed_by_user_id uuid NOT NULL, decision varchar(24) NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_ai_action_draft_account ON orcafacil.ai_action_drafts(account_id, status);
CREATE TABLE IF NOT EXISTS orcafacil.ai_provider_health_checks (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_provider_health_checks_account ON orcafacil.ai_provider_health_checks(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_prompt_templates (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_prompt_templates_account ON orcafacil.ai_prompt_templates(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_prompt_template_versions (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_prompt_template_versions_account ON orcafacil.ai_prompt_template_versions(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_interactions (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_interactions_account ON orcafacil.ai_interactions(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_interaction_messages (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_interaction_messages_account ON orcafacil.ai_interaction_messages(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_interaction_sources (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_interaction_sources_account ON orcafacil.ai_interaction_sources(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_safety_events (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_safety_events_account ON orcafacil.ai_safety_events(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_embeddings (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_embeddings_account ON orcafacil.ai_embeddings(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_embedding_jobs (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_embedding_jobs_account ON orcafacil.ai_embedding_jobs(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_document_analysis_jobs (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_document_analysis_jobs_account ON orcafacil.ai_document_analysis_jobs(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_document_analysis_results (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_document_analysis_results_account ON orcafacil.ai_document_analysis_results(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_document_extractions (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_document_extractions_account ON orcafacil.ai_document_extractions(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_suggestion_cards (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_suggestion_cards_account ON orcafacil.ai_suggestion_cards(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_redaction_rules (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_redaction_rules_account ON orcafacil.ai_redaction_rules(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_feedback_events (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_feedback_events_account ON orcafacil.ai_feedback_events(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.ai_cost_usage_snapshots (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_ai_cost_usage_snapshots_account ON orcafacil.ai_cost_usage_snapshots(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.semantic_search_indexes (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_semantic_search_indexes_account ON orcafacil.semantic_search_indexes(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.semantic_search_queries (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_semantic_search_queries_account ON orcafacil.semantic_search_queries(account_id, created_at DESC);
CREATE TABLE IF NOT EXISTS orcafacil.semantic_search_results (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_semantic_search_results_account ON orcafacil.semantic_search_results(account_id, created_at DESC);
